	@Test
	void rejectsDuplicateActiveIdsAndAllowsReuseAfterCompletion() {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		CancellableOperationCoordinator.Handle first = coordinator.register("request-1");

		assertThatThrownBy(() -> coordinator.register("request-1"))
				.isInstanceOf(IllegalStateException.class)
				.hasMessage("Request already active: request-1");

		coordinator.complete(first);
		CancellableOperationCoordinator.Handle second = coordinator.register("request-1");

		assertThat(second).isNotSameAs(first);
		coordinator.complete(second);
	}

